 void auth(){base();Space sp=new Space(this);root.addView(sp,new LinearLayout.LayoutParams(1,d(54)));LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER_HORIZONTAL);card.setPadding(d(24),d(24),d(24),d(22));card.setBackground(outline(Color.WHITE,line,23));root.addView(card,new LinearLayout.LayoutParams(-1,-2));card.addView(logo(104));TextView h=title("Crisálida",29);h.setPadding(0,d(12),0,d(3));card.addView(h);TextView sub=txt("Um espaço para transformar ideias em ação.",14,muted);sub.setPadding(0,0,0,d(22));card.addView(sub);EditText user=field("Username");EditText pass=field("Senha");pass.setInputType(0x81);card.addView(user);card.addView(pass);TextView err=txt("",13,Color.rgb(190,55,70));err.setPadding(0,0,0,d(8));card.addView(err);Button enter=button("Entrar");enter.setTextColor(Color.WHITE);enter.setBackground(fill(ink,14));card.addView(enter,new LinearLayout.LayoutParams(-1,d(50)));Button create=button("Criar nova conta");create.setTextColor(violet);create.setBackgroundColor(Color.TRANSPARENT);card.addView(create,new LinearLayout.LayoutParams(-1,d(48)));enter.setOnClickListener(v->{String n=user.getText().toString().trim();if(store.getString("user_"+n,"").equals(hash(pass.getText().toString()))){store.edit().putBoolean("logged",true).putString("name",n).apply();home();}else err.setText("Username ou senha incorretos.");});create.setOnClickListener(v->{String n=user.getText().toString().trim(),q=pass.getText().toString();if(n.length()<3||q.length()<4){err.setText("Username com 3+ e senha com 4+ caracteres.");return;}if(store.contains("user_"+n)){err.setText("Este username já existe neste aparelho.");return;}store.edit().putString("user_"+n,hash(q)).putBoolean("logged",true).putString("name",n).apply();home();});}
