 void composerCard(){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(d(16),d(15),d(12),d(12));card.setBackground(outline(Color.WHITE,line,20));TextView hint=txt("Descreva o que você quer fazer...",14,muted);card.addView(hint);composer=new EditText(this);composer.setHint("Ex.: pesquise, analise e me entregue um plano...");composer.setHintTextColor(Color.rgb(164,158,171));composer.setTextColor(ink);composer.setTextSize(16);composer.setGravity(Gravity.TOP);composer.setMinLines(3);composer.setPadding(0,d(10),0,0);composer.setBackgroundColor(Color.TRANSPARENT);card.addView(composer,new LinearLayout.LayoutParams(-1,d(85)));LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.CENTER_VERTICAL);TextView attach=txt("＋",26,muted);actions.addView(attach,new LinearLayout.LayoutParams(d(40),d(42)));model=new Spinner(this);modelAdapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,env.models);model.setAdapter(modelAdapter);actions.addView(model,new LinearLayout.LayoutParams(0,d(42),1));TextView send=txt("↑",24,Color.WHITE);send.setGravity(Gravity.CENTER);send.setBackground(fill(ink,30));actions.addView(send,new LinearLayout.LayoutParams(d(42),d(42)));send.setOnClickListener(v->{String q=composer.getText().toString().trim();if(!q.isEmpty())openChat(q);});card.addView(actions);content.addView(card,new LinearLayout.LayoutParams(-1,-2));}
 void quickActions(){HorizontalScrollView hs=new HorizontalScrollView(this);hs.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(this);row.setPadding(0,0,d(10),0);String[][] a={{"✦","Pesquisar","Explore qualquer tema"},{"▣","Criar","Transforme ideias em conteúdo"},{"⌘","Código","Construa e analise"},{"◌","Analisar","Entenda seus arquivos"}};for(String[] x:a){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(d(14),d(13),d(14),d(12));c.setBackground(outline(Color.WHITE,line,17));TextView ic=txt(x[0],22,violet);c.addView(ic);TextView n=title(x[1],14);n.setPadding(0,d(8),0,0);c.addView(n);c.addView(txt(x[2],11,muted));c.setOnClickListener(v->openChat(""));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(d(155),d(116));p.setMargins(0,0,d(10),0);row.addView(c,p);}hs.addView(row);content.addView(hs);}
 void recent(String a,String b,String arrow){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(d(14),d(10),d(10),d(10));r.setBackground(outline(Color.WHITE,line,15));LinearLayout t=new LinearLayout(this);t.setOrientation(LinearLayout.VERTICAL);t.addView(txt(a,14,ink));t.addView(txt(b,12,muted));r.addView(t,new LinearLayout.LayoutParams(0,d(58),1));r.addView(txt(arrow,25,muted));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,d(78));p.setMargins(0,0,0,d(9));content.addView(r,p);}
 void bottomNav(int selected){LinearLayout n=new LinearLayout(this);n.setGravity(Gravity.CENTER);n.setPadding(0,d(5),0,d(5));String[] labels={"⌂  Início","□  Tarefas","○  Perfil"};for(int i=0;i<3;i++){TextView x=txt(labels[i],12,i==selected?violet:muted);x.setGravity(Gravity.CENTER);n.addView(x,new LinearLayout.LayoutParams(0,d(42),1));}root.addView(n,new LinearLayout.LayoutParams(-1,d(52)));}
 void openChat(String first){base();header(true);sync=txt("",12,muted);sync.setPadding(d(52),0,0,d(4));root.addView(sync);ScrollView scroll=new ScrollView(this);messages=new LinearLayout(this);messages.setOrientation(LinearLayout.VERTICAL);messages.setPadding(0,d(16),0,d(12));scroll.addView(messages);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));if(first.isEmpty()){bubble("Como posso ajudar?",false);}else{bubble(first,true);ask(first);}LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(d(12),0,d(5),0);bar.setBackground(outline(Color.WHITE,line,20));EditText e=new EditText(this);e.setHint("Continue a conversa...");e.setHintTextColor(muted);e.setTextColor(ink);e.setTextSize(15);e.setBackgroundColor(Color.TRANSPARENT);bar.addView(e,new LinearLayout.LayoutParams(0,d(58),1));TextView go=txt("↑",23,Color.WHITE);go.setGravity(Gravity.CENTER);go.setBackground(fill(ink,30));bar.addView(go,new LinearLayout.LayoutParams(d(42),d(42)));go.setOnClickListener(v->{String q=e.getText().toString().trim();if(!q.isEmpty()){bubble(q,true);e.setText("");ask(q);}});root.addView(bar,new LinearLayout.LayoutParams(-1,d(64)));}
 void bubble(String s,boolean mine){TextView v=txt(s,15,mine?Color.WHITE:ink);v.setTextIsSelectable(true);v.setPadding(d(15),d(12),d(15),d(12));v.setBackground(fill(mine?ink:Color.WHITE,17));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.setMargins(mine?d(35):0,d(5),mine?0:d(35),d(5));p.gravity=mine?Gravity.RIGHT:Gravity.LEFT;messages.addView(v,p);}
 void ask(String q){TextView wait=txt("Crisálida está trabalhando…",14,muted);messages.addView(wait);String m=env.models.isEmpty()?"Crisálida Lite":env.models.get(Math.max(0,model==null?0:model.getSelectedItemPosition()));String selected=env.keyFor(m);new Thread(()->{try{JSONObject j=new JSONObject();j.put("model",m);j.put("stream",false);j.put("web_search",env.web);j.put("code_interpreter",env.code);j.put("reasoning",env.reasoning);JSONArray a=new JSONArray();JSONObject u=new JSONObject();u.put("role","user");u.put("content",q);a.put(u);j.put("messages",a);String out=Http.post(join(env.base,"chat/completions"),j.toString(),selected);String ans=new JSONObject(out).optJSONArray("choices").getJSONObject(0).getJSONObject("message").optString("content",out);runOnUiThread(()->{messages.removeView(wait);bubble(ans,false);});}catch(Exception e){runOnUiThread(()->{messages.removeView(wait);bubble("Não consegui concluir: "+e.getMessage(),false);});}}).start();}
 void loadEnv(){sync.setText("Atualizando configuração…");new Thread(()->{try{env=Env.parse(Http.get(ENV_URL,""));runOnUiThread(()->{if(modelAdapter!=null){modelAdapter.clear();modelAdapter.addAll(env.models);modelAdapter.notifyDataSetChanged();}sync.setText("Atualizado agora");});}catch(Exception e){runOnUiThread(()->sync.setText("Não foi possível sincronizar"));}}).start();}
 void schedule(){Constraints c=new Constraints.Builder().setRequiredNetworkType(NetworkType.CONNECTED).build();PeriodicWorkRequest w=new PeriodicWorkRequest.Builder(EnvWorker.class,15,java.util.concurrent.TimeUnit.MINUTES).setConstraints(c).build();WorkManager.getInstance(this).enqueueUniquePeriodicWork("env-sync",ExistingPeriodicWorkPolicy.UPDATE,w);}
 public static class EnvWorker extends Worker{public EnvWorker(Context c,WorkerParameters p){super(c,p);}public Result doWork(){try{Http.get(ENV_URL,"");return Result.success();}catch(Exception e){return Result.retry();}}}
 static class Env{String base="",key="";Map<String,String> keys=new HashMap<>();boolean web=true,code=true,reasoning=true;List<String> models=new ArrayList<>();static Env parse(String s){Env e=new Env();for(String line:s.split("\\n")){line=line.trim();if(line.isEmpty()||line.startsWith("#")||!line.contains("="))continue;int k=line.indexOf('=');String a=line.substring(0,k).trim(),v=line.substring(k+1).trim();if(v.startsWith("\"")&&v.endsWith("\""))v=v.substring(1,v.length()-1);if(a.equals("API_BASE_URL"))e.base=v;else if(a.equals("API_KEY"))e.key=v;else if(a.startsWith("KEY_")||a.startsWith("API_KEY_")){String mk=a.replaceFirst("^API_KEY_?","");e.keys.put(mk,v);}else if(a.equals("MODELS"))for(String m:v.split(","))if(!m.trim().isEmpty())e.models.add(m.trim());else if(a.equals("WEB_SEARCH"))e.web=Boolean.parseBoolean(v);else if(a.equals("CODE_INTERPRETER"))e.code=Boolean.parseBoolean(v);else if(a.equals("REASONING"))e.reasoning=Boolean.parseBoolean(v);}return e;}String keyFor(String model){String n=model.toUpperCase(Locale.ROOT).replaceAll("[^A-Z0-9]+","_").replaceAll("^_|_$","");String k=keys.get(n);return k==null||k.isEmpty()?key:k;}}
 static String hash(String s){try{byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder x=new StringBuilder();for(byte z:b)x.append(String.format("%02x",z));return x.toString();}catch(Exception e){return"";}}static String join(String b,String p){b=b.replaceAll("/+$","");return b.endsWith("/v1")?b+"/"+p:b+"/v1/"+p;}
 static class Http{static byte[] readAll(InputStream in)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)b.write(buf,0,n);return b.toByteArray();}static String get(String u,String k)throws Exception{return req("GET",u,null,k);}static String post(String u,String b,String k)throws Exception{return req("POST",u,b,k);}static String req(String m,String u,String body,String k)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setRequestMethod(m);c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("Accept","text/plain, application/json");if(k!=null&&!k.isEmpty())c.setRequestProperty("Authorization","Bearer "+k);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes(StandardCharsets.UTF_8));}}int n=c.getResponseCode();InputStream in=n>=400?c.getErrorStream():c.getInputStream();String s=new String(readAll(in),StandardCharsets.UTF_8);if(n>=400)throw new IOException(n+" "+s);return s;}}
